import { useState, useEffect, useCallback } from "react";
import { TestProgressHeader } from "../shared/UI";

const ROUNDS = [
  { highlight: 3, label: "Round 1 — Easy" },
  { highlight: 5, label: "Round 2 — Medium" },
  { highlight: 7, label: "Round 3 — Hard" },
];

function randomCells(count, total = 16) {
  const all = Array.from({ length: total }, (_, i) => i);
  for (let i = all.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [all[i], all[j]] = [all[j], all[i]];
  }
  return all.slice(0, count);
}

export default function PatternRecognition({ onComplete, testIndex, totalTests }) {
  const [round, setRound] = useState(0);
  const [phase, setPhase] = useState("show"); // show | recall
  const [pattern, setPattern] = useState(() => randomCells(ROUNDS[0].highlight));
  const [selected, setSelected] = useState([]);
  const [roundScores, setRoundScores] = useState([]);
  const [started] = useState(Date.now());
  const SHOW_MS = 4000;

  useEffect(() => {
    if (phase !== "show") return;
    const t = setTimeout(() => setPhase("recall"), SHOW_MS);
    return () => clearTimeout(t);
  }, [phase, round]);

  const toggleCell = (i) => {
    if (phase !== "recall") return;
    setSelected(s => s.includes(i) ? s.filter(x => x !== i) : [...s, i]);
  };

  const handleSubmit = useCallback(() => {
    const correct = selected.filter(i => pattern.includes(i)).length;
    const newScores = [...roundScores, correct];
    setRoundScores(newScores);

    if (round + 1 >= ROUNDS.length) {
      // finalize
      const totalCorrect = newScores.reduce((a, b) => a + b, 0);
      const totalPossible = ROUNDS.reduce((a, r) => a + r.highlight, 0);
      const score = Math.round((totalCorrect / totalPossible) * 5);
      const time = Math.round((Date.now() - started) / 1000);
      const responses = newScores.map((correct, i) => ({
        round: i + 1,
        correct,
        possible: ROUNDS[i].highlight,
      }));
      onComplete({ score, maxScore: 5, timeTaken: time, responses });
    } else {
      const nextRound = round + 1;
      setRound(nextRound);
      setPattern(randomCells(ROUNDS[nextRound].highlight));
      setSelected([]);
      setPhase("show");
    }
  }, [selected, pattern, roundScores, round, started, onComplete]);

  return (
    <div className="page-enter">
      <TestProgressHeader current={testIndex + 1} total={totalTests} testName="Pattern Recognition" />

      <div className="card max-w-lg mx-auto text-center">
        <div className="flex gap-2 justify-center mb-4">
          {ROUNDS.map((r, i) => (
            <span key={i} className={`px-3 py-1 rounded-full text-xs font-semibold ${i === round ? "bg-brand-600 text-white" : i < round ? "bg-green-100 text-green-700" : "bg-slate-100 text-slate-400"}`}>
              {r.label}
            </span>
          ))}
        </div>

        {phase === "show" ? (
          <>
            <p className="text-sm text-slate-500 mb-6">
              Memorize the highlighted squares! They disappear in {SHOW_MS / 1000}s.
            </p>
            <div className="grid grid-cols-4 gap-2 w-64 mx-auto">
              {Array.from({ length: 16 }, (_, i) => (
                <div key={i} className={`h-14 rounded-xl transition-all duration-300 ${
                  pattern.includes(i) ? "bg-brand-500 shadow-lg shadow-brand-200" : "bg-slate-100"
                }`} />
              ))}
            </div>
          </>
        ) : (
          <>
            <p className="text-sm text-slate-500 mb-6">
              Click the squares that were highlighted.
              <span className="font-semibold text-brand-600"> ({ROUNDS[round].highlight} squares)</span>
            </p>
            <div className="grid grid-cols-4 gap-2 w-64 mx-auto mb-6">
              {Array.from({ length: 16 }, (_, i) => (
                <button key={i}
                  onClick={() => toggleCell(i)}
                  className={`h-14 rounded-xl transition-all ${
                    selected.includes(i) ? "bg-brand-500 shadow-md scale-95" : "bg-slate-100 hover:bg-slate-200"
                  }`}
                />
              ))}
            </div>
            <p className="text-xs text-slate-400 mb-4">{selected.length} of {ROUNDS[round].highlight} selected</p>
            <button onClick={handleSubmit} className="btn-primary">
              {round + 1 < ROUNDS.length ? "Next Round →" : "Finish Test →"}
            </button>
          </>
        )}
      </div>
    </div>
  );
}
